def _as_bytes(message: Any) -> bytes:
    if isinstance(message, bytes):
        return message
    if isinstance(message, bytearray):
        return bytes(message)
    if isinstance(message, str):
        return message.encode("utf-8")
    raise TypeError("message must be bytes, bytearray or str")


def _validate_w(w: Any) -> int:
    if isinstance(w, bool) or not isinstance(w, int) or w not in _ALLOWED_W:
        raise ValueError("w must be 4 or 8")
    return w


def _params(w: int) -> tuple[int, int, int]:
    """Return ``(B, l1, l2)``: base, message digit count, checksum digit count."""
    b = 1 << w
    l1 = 256 // w
    l2 = 1
    limit = l1 * (b - 1)
    while b ** l2 <= limit:
        l2 += 1
    return b, l1, l2


def _validate_elements(w: int, elements: Any) -> None:
    if not isinstance(elements, tuple):
        raise TypeError("elements must be a tuple of 32-byte values")
    _, l1, l2 = _params(w)
    if len(elements) != l1 + l2:
        raise ValueError(f"elements must contain exactly {l1 + l2} values for w={w}")
    for element in elements:
        if not isinstance(element, bytes) or len(element) != ELEMENT_BYTES:
            raise ValueError(f"every element must be exactly {ELEMENT_BYTES} bytes")


def _chain_count(w: int) -> int:
    _, l1, l2 = _params(w)
    return l1 + l2


def _encode_v1(magic: bytes, w: int, elements: tuple[bytes, ...]) -> bytes:
    """Shared v1 layout: magic, version, ``w``, element count, elements."""
    return (
        magic
        + bytes((_CODEC_VERSION, w))
        + len(elements).to_bytes(2, "big")
        + b"".join(elements)
    )


def _decode_v1(data: Any, magic: bytes, name: str) -> tuple[int, tuple[bytes, ...]]:
    """Parse a v1 blob into ``(w, elements)``; ``name`` labels error messages."""
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError(f"{name} data must be bytes or bytearray")
    data = bytes(data)
    if len(data) < _CODEC_HEADER_BYTES:
        raise ValueError(f"{name} encoding is truncated")
    if data[:8] != magic:
        raise ValueError(f"bad {name} magic")
    if data[8] != _CODEC_VERSION:
        raise ValueError(f"unsupported {name} version: {data[8]}")
    w = _validate_w(data[9])
    element_count = int.from_bytes(data[10:12], "big")
    chains = _chain_count(w)
    if element_count != chains:
        raise ValueError("element count does not match the chain count for w")
    expected = _CODEC_HEADER_BYTES + element_count * ELEMENT_BYTES
    if len(data) < expected:
        raise ValueError(f"{name} encoding is truncated")
    if len(data) > expected:
        raise ValueError(f"trailing data after the {name} encoding")
    elements = tuple(
        data[_CODEC_HEADER_BYTES + i * ELEMENT_BYTES : _CODEC_HEADER_BYTES + (i + 1) * ELEMENT_BYTES]
        for i in range(element_count)
    )
    return w, elements


def _key_to_bytes(key: Any, key_type: type, magic: bytes, name: str) -> bytes:
    if not isinstance(key, key_type):
        raise TypeError(f"to_bytes must be called on a {key_type.__name__}")
    try:
        w = _validate_w(key.w)
        _validate_elements(w, key.elements)
    except TypeError as exc:
        raise ValueError(f"corrupted {name}: {exc}") from exc
    return _encode_v1(magic, w, key.elements)


@dataclass(frozen=True)
class WOTSPrivateKey:
    """Frozen W-OTS private key.

    ``elements`` holds the random step-0 start value of every chain: the
    ``l1`` message chains followed by the ``l2`` checksum chains.
    """

    w: int
    elements: tuple[bytes, ...]

    def __post_init__(self) -> None:
        w = _validate_w(self.w)
        _validate_elements(w, self.elements)

    @property
    def length(self) -> int:
        """Number of chains (and signature elements): ``l1 + l2``."""
        return len(self.elements)

    def to_bytes(self) -> bytes:
        """Serialise to the versioned v1 wire format as ``bytes``.

        The layout is the 8-byte magic ``b"PQAWPRV\\0"``; one byte each for
        the version (1) and ``w``; the element count as 2 big-endian bytes
        (67 for ``w=4``, 34 for ``w=8``); then every private element in chain
        order, 32 bytes each. Encoding is deterministic: the same key always
        produces the same bytes. Fields corrupted by bypassing the frozen
        constructor raise ``ValueError`` instead of producing a malformed
        encoding. The blob contains the private key in the clear — store it
        as a secret.
        """
        return _key_to_bytes(self, WOTSPrivateKey, _PRIVATE_KEY_MAGIC, "private key")

    @classmethod
    def from_bytes(cls, data: Any) -> "WOTSPrivateKey":
        """Parse ``to_bytes()`` output back into a :class:`WOTSPrivateKey`.

        ``data`` must be ``bytes`` or ``bytearray``; anything else raises
        ``TypeError``. A bad magic, an unknown version, an invalid ``w``, an
        element count that does not match the chain count for ``w``,
        truncation or trailing data raises ``ValueError`` and no instance is
        returned. The restored key is equal by value to the original.
        """
        w, elements = _decode_v1(data, _PRIVATE_KEY_MAGIC, "private key")
        return cls(w=w, elements=elements)


@dataclass(frozen=True)
class WOTSPublicKey:
    """Frozen W-OTS public key: the step ``B - 1`` endpoint of every chain."""

    w: int
    elements: tuple[bytes, ...]

    def __post_init__(self) -> None:
        w = _validate_w(self.w)
        _validate_elements(w, self.elements)

    @property
    def length(self) -> int:
        """Number of chains (and signature elements): ``l1 + l2``."""
        return len(self.elements)

    def to_bytes(self) -> bytes:
        """Serialise to the versioned v1 wire format as ``bytes``.

        The layout is the 8-byte magic ``b"PQAWPUB\\0"``; one byte each for
        the version (1) and ``w``; the element count as 2 big-endian bytes
        (67 for ``w=4``, 34 for ``w=8``); then every public element in chain
        order, 32 bytes each. Encoding is deterministic: the same key always
        produces the same bytes. Fields corrupted by bypassing the frozen
        constructor raise ``ValueError`` instead of producing a malformed
        encoding.
        """
        return _key_to_bytes(self, WOTSPublicKey, _PUBLIC_KEY_MAGIC, "public key")

    @classmethod
    def from_bytes(cls, data: Any) -> "WOTSPublicKey":
        """Parse ``to_bytes()`` output back into a :class:`WOTSPublicKey`.

        ``data`` must be ``bytes`` or ``bytearray``; anything else raises
        ``TypeError``. A bad magic, an unknown version, an invalid ``w``, an
        element count that does not match the chain count for ``w``,
        truncation or trailing data raises ``ValueError`` and no instance is
        returned. The restored key is equal by value to the original.
        """
        w, elements = _decode_v1(data, _PUBLIC_KEY_MAGIC, "public key")
        return cls(w=w, elements=elements)


def _chain_step(value: bytes) -> bytes:
    return hashlib.sha256(_DOMAIN + value).digest()


def _chain_walk(value: bytes, steps: int) -> bytes:
    for _ in range(steps):
        value = _chain_step(value)
    return value


def _message_digits(digest: bytes, w: int, b: int, l1: int) -> tuple[int, ...]:
    """Split a 256-bit digest into ``l1`` base-``B`` digits, big endian."""
    value = int.from_bytes(digest, "big")
    return tuple((value >> (256 - w * (i + 1))) & (b - 1) for i in range(l1))


def _checksum_digits(
    message_digits: Iterable[int], w: int, b: int, l2: int
) -> tuple[int, ...]:
    """``sum(B - 1 - d)`` as exactly ``l2`` base-``B`` digits, leading zeros kept."""
    checksum = sum(b - 1 - digit for digit in message_digits)
    return tuple((checksum >> (w * (l2 - 1 - i))) & (b - 1) for i in range(l2))


def _signing_digits(message: Any, w: int) -> tuple[int, ...]:
    b, l1, l2 = _params(w)
    digest = hashlib.sha256(_as_bytes(message)).digest()
    message_part = _message_digits(digest, w, b, l1)
    return message_part + _checksum_digits(message_part, w, b, l2)


class WOTSOneTimeSigner:
    """Thread-safe, single-use wrapper around a :class:`WOTSPrivateKey`.

    The first :meth:`sign` call returns the ordinary :func:`wots_sign`
    signature and marks the key as used; every later call raises
    :class:`~pqattest.KeyExhaustedError`. The guard is per instance and per
    process — copying the private key, calling the stateless :func:`wots_sign`
    directly or reusing the key in another process is the caller's
    responsibility. State can be persisted with :meth:`checkpoint` and
    restored in another process with :meth:`from_checkpoint`; the checkpoint
    contains the private key in the clear and is protected only by a SHA-256
    checksum against accidental corruption, so callers must store it securely.
    """

    __slots__ = ("_lock", "_private_key", "_public_key", "_used")

    def __init__(self, private_key: WOTSPrivateKey) -> None:
        if not isinstance(private_key, WOTSPrivateKey):
            raise TypeError("private_key must be a WOTSPrivateKey")
        self._restore_state(private_key, self._public_key_from(private_key), False)

    @staticmethod
    def _public_key_from(private_key: WOTSPrivateKey) -> WOTSPublicKey:
        b = 1 << private_key.w

import unittest

from pqattest import MerklePublicKey, MerkleSignature, MerkleSigner, merkle_verify
from pqattest.merkle import (
    _PUBLIC_KEY_MAGIC,
    _SIGNATURE_MAGIC,
    _SIGNATURE_HEADER_BYTES,
)
from pqattest.wots import _params


def counter_tokens(start: int = 0):
    state = {"value": start}

    def token_bytes(size: int) -> bytes:
        state["value"] += 1
        return state["value"].to_bytes(8, "big").rjust(size, b"\x00")

    return token_bytes


def make_signer(height=2, w=4, start=0):
    return MerkleSigner(height=height, w=w, token_bytes=counter_tokens(start))


def chains_for(w):
    _, l1, l2 = _params(w)
    return l1 + l2


class PublicKeyFormatTest(unittest.TestCase):
    def test_layout_and_length(self):
        for w in (4, 8):
            with self.subTest(w=w):
                signer = make_signer(height=3, w=w)
                blob = signer.public_key.to_bytes()
                self.assertEqual(len(blob), 8 + 1 + 1 + 1 + 32)
                self.assertEqual(blob[:8], _PUBLIC_KEY_MAGIC)
                self.assertEqual(blob[8], 1)  # version
                self.assertEqual(blob[9], w)
                self.assertEqual(blob[10], 3)  # height
                self.assertEqual(blob[11:], signer.public_key.root)

    def test_to_bytes_returns_bytes(self):
        self.assertIsInstance(make_signer().public_key.to_bytes(), bytes)

    def test_encoding_is_deterministic(self):
        key = make_signer().public_key
        self.assertEqual(key.to_bytes(), key.to_bytes())


class PublicKeyRoundTripTest(unittest.TestCase):
    def test_round_trip_all_w_and_heights(self):
        for w in (4, 8):
            for height in (1, 2, 5, 8):
                with self.subTest(w=w, height=height):
                    key = make_signer(height=height, w=w).public_key
                    restored = MerklePublicKey.from_bytes(key.to_bytes())
                    self.assertEqual(restored, key)
                    self.assertEqual(restored.to_bytes(), key.to_bytes())

    def test_accepts_bytearray(self):
        key = make_signer().public_key
        restored = MerklePublicKey.from_bytes(bytearray(key.to_bytes()))
        self.assertEqual(restored, key)


class PublicKeyValidationTest(unittest.TestCase):
    def setUp(self):
        self.blob = make_signer(height=2).public_key.to_bytes()

    def test_non_bytes_types_raise_type_error(self):
        for bad in (None, 42, 4.5, "key", [self.blob], (self.blob,), object()):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    MerklePublicKey.from_bytes(bad)

    def test_truncated_and_empty_rejected(self):
        for cut in (0, 7, 20, len(self.blob) - 1):
            with self.subTest(cut=cut):
                with self.assertRaises(ValueError):
                    MerklePublicKey.from_bytes(self.blob[:cut])

    def test_trailing_data_rejected(self):
        with self.assertRaises(ValueError):
            MerklePublicKey.from_bytes(self.blob + b"\x00")

    def test_bad_magic_rejected(self):
        bad = bytearray(self.blob)
        bad[0] ^= 0x01
        with self.assertRaises(ValueError):
            MerklePublicKey.from_bytes(bytes(bad))

    def test_bad_version_rejected(self):
        for version in (0, 2, 255):
            with self.subTest(version=version):
                bad = bytearray(self.blob)
                bad[8] = version
                with self.assertRaises(ValueError):
                    MerklePublicKey.from_bytes(bytes(bad))

    def test_bad_w_rejected(self):
        for bad_w in (0, 2, 16, 255):
            with self.subTest(bad_w=bad_w):
                bad = bytearray(self.blob)
                bad[9] = bad_w
                with self.assertRaises(ValueError):
                    MerklePublicKey.from_bytes(bytes(bad))

    def test_bad_height_rejected(self):
        for bad_height in (0, 9, 255):
            with self.subTest(bad_height=bad_height):
                bad = bytearray(self.blob)
                bad[10] = bad_height
                with self.assertRaises(ValueError):
                    MerklePublicKey.from_bytes(bytes(bad))

    def test_to_bytes_on_foreign_object_raises_type_error(self):
        for bad in (None, 42, "key", object()):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    MerklePublicKey.to_bytes(bad)


class SignatureFormatTest(unittest.TestCase):
    def test_layout_and_length(self):
        for w in (4, 8):
            with self.subTest(w=w):
                signer = make_signer(height=3, w=w)
                signer.sign("spent")
                signature = signer.sign("message")
                blob = signature.to_bytes(signer.public_key)
                chains = chains_for(w)
                self.assertEqual(
                    len(blob), _SIGNATURE_HEADER_BYTES + (chains + 3) * 32
                )
                self.assertEqual(blob[:8], _SIGNATURE_MAGIC)
                self.assertEqual(blob[8], 1)  # version
                self.assertEqual(blob[9], w)
                self.assertEqual(blob[10], 3)  # height
                self.assertEqual(int.from_bytes(blob[11:13], "big"), 1)  # index
                self.assertEqual(int.from_bytes(blob[13:15], "big"), chains)
                self.assertEqual(blob[15], 3)  # path count
                offset = _SIGNATURE_HEADER_BYTES
                self.assertEqual(
                    blob[offset : offset + chains * 32],
                    b"".join(signature.wots_signature),
                )
                self.assertEqual(
                    blob[offset + chains * 32 :],
                    b"".join(signature.auth_path),
                )

    def test_to_bytes_returns_bytes(self):
        signer = make_signer()
        signature = signer.sign("m")
        self.assertIsInstance(signature.to_bytes(signer.public_key), bytes)

    def test_encoding_is_deterministic(self):
        signer = make_signer()
        signature = signer.sign("m")
        self.assertEqual(
            signature.to_bytes(signer.public_key),
            signature.to_bytes(signer.public_key),
        )


class SignatureRoundTripTest(unittest.TestCase):
    def test_round_trip_all_w_and_heights(self):
        for w in (4, 8):
            for height in (1, 2, 5, 8):
                with self.subTest(w=w, height=height):
                    signer = make_signer(height=height, w=w)
                    for message in ("one", "two"):
                        signature = signer.sign(message)
                        blob = signature.to_bytes(signer.public_key)
                        restored = MerkleSignature.from_bytes(
                            blob, signer.public_key
                        )
                        self.assertEqual(restored, signature)
                        self.assertTrue(
                            merkle_verify(message, restored, signer.public_key)
                        )

    def test_accepts_bytearray(self):
        signer = make_signer()
        signature = signer.sign("m")
        blob = signature.to_bytes(signer.public_key)
        restored = MerkleSignature.from_bytes(bytearray(blob), signer.public_key)
        self.assertEqual(restored, signature)

    def test_public_key_round_trips_with_signature(self):
        signer = make_signer(height=3, w=8)
        signature = signer.sign("m")
        key = MerklePublicKey.from_bytes(signer.public_key.to_bytes())
        restored = MerkleSignature.from_bytes(signature.to_bytes(key), key)
        self.assertTrue(merkle_verify("m", restored, key))


class SignatureValidationTest(unittest.TestCase):
    def setUp(self):
        self.signer = make_signer(height=2)
        self.signer.sign("spent")
        self.signature = self.signer.sign("message")
        self.public_key = self.signer.public_key
        self.blob = self.signature.to_bytes(self.public_key)

    def assert_rejected(self, data, public_key=None):
        with self.assertRaises(ValueError):
            MerkleSignature.from_bytes(
                data, self.public_key if public_key is None else public_key
            )

    def test_non_bytes_data_raises_type_error(self):
        for bad in (None, 42, 4.5, "sig", [self.blob], (self.blob,), object()):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    MerkleSignature.from_bytes(bad, self.public_key)

    def test_non_public_key_raises_type_error(self):
        for bad in (None, 42, "key", self.blob, object()):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    MerkleSignature.from_bytes(self.blob, bad)
                with self.assertRaises(TypeError):
                    self.signature.to_bytes(bad)

    def test_to_bytes_on_foreign_object_raises_type_error(self):
        for bad in (None, 42, "sig", object()):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    MerkleSignature.to_bytes(bad, self.public_key)

    def test_truncated_and_empty_rejected(self):
        self.assert_rejected(b"")
        self.assert_rejected(self.blob[:10])
        self.assert_rejected(self.blob[: _SIGNATURE_HEADER_BYTES])
        self.assert_rejected(self.blob[:-1])

    def test_trailing_data_rejected(self):
        self.assert_rejected(self.blob + b"\x00")

    def test_bad_magic_rejected(self):
        bad = bytearray(self.blob)
        bad[0] ^= 0x01
        self.assert_rejected(bytes(bad))

    def test_bad_version_rejected(self):
        bad = bytearray(self.blob)
        bad[8] = 2
        self.assert_rejected(bytes(bad))

    def test_w_mismatch_rejected(self):
        other = make_signer(height=2, w=8, start=1000)
        self.assert_rejected(self.blob, public_key=other.public_key)
        bad = bytearray(self.blob)
        bad[9] = 8
        self.assert_rejected(bytes(bad))

    def test_height_mismatch_rejected(self):
        other = make_signer(height=3, start=1000)
        self.assert_rejected(self.blob, public_key=other.public_key)
        bad = bytearray(self.blob)
        bad[10] = 3
        self.assert_rejected(bytes(bad))

    def test_out_of_range_index_rejected(self):
        bad = bytearray(self.blob)
        bad[11:13] = (4).to_bytes(2, "big")  # height 2 -> 4 leaves
        self.assert_rejected(bytes(bad))

    def test_bad_element_count_rejected(self):
        chains = chains_for(self.public_key.w)
        for count in (0, chains - 1, chains + 1):
            with self.subTest(count=count):
                bad = bytearray(self.blob)
                bad[13:15] = count.to_bytes(2, "big")
                self.assert_rejected(bytes(bad))

    def test_bad_path_count_rejected(self):
        for count in (0, 1, 3, 255):
            with self.subTest(count=count):
                bad = bytearray(self.blob)
                bad[15] = count
                self.assert_rejected(bytes(bad))

    def test_to_bytes_rejects_signature_inconsistent_with_key(self):
        other = make_signer(height=3, w=8, start=1000)
        with self.assertRaises(ValueError):
            self.signature.to_bytes(other.public_key)

    def test_valid_signature_still_accepted(self):
        # Guard against the corruption tests making the helper too strict.
        restored = MerkleSignature.from_bytes(self.blob, self.public_key)
        self.assertEqual(restored, self.signature)
        self.assertTrue(merkle_verify("message", restored, self.public_key))


if __name__ == "__main__":
    unittest.main()

